import json, sys
d = json.load(open(sys.argv[1]))
out_path = sys.argv[2]
ORDER = ["LowerTorso","UpperTorso","Head","RightUpperArm","RightLowerArm","RightHand","LeftUpperArm","LeftLowerArm","LeftHand","RightUpperLeg","RightLowerLeg","RightFoot","LeftUpperLeg","LeftLowerLeg","LeftFoot"]
L = ['--!strict', '--[[',
     "\tUalClips: survivor combat clips retargeted from Quaternius's Universal Animation",
     "\tLibrary (CC0; Zona assets-src/characters/ual) onto the R15 survivor. Generated by a",
     "\tscript, never edited by hand. Each key has a time and one rotation per part in PARTS",
     "\torder, as a quaternion (x, y, z, w) in character space: the part's turn relative to",
     "\tits parent part, measured from the survivor rig's rest pose (arms hanging down).",
     "\tLowerTorso adds its offset from the HumanoidRootPart in studs. Controllers turn each",
     "\trotation into its joint's frame (CombatControl.ualClip).",
     ']]', '', 'local UalClips = {}', '', 'UalClips.PARTS = {']
for p in ORDER:
    L.append(f'\t"{p}",')
L += ['}', '', 'export type Key = { t: number, p: { { number } } }', 'export type Clip = { length: number, keys: { Key } }', '', 'UalClips.clips = {']
for name, c in d.items():
    if name == "Idle_Loop":
        continue
    L.append(f'\t{name} = {{')
    L.append(f'\t\tlength = {c["length"]},')
    L.append('\t\tkeys = {')
    for k in c["keys"]:
        vals = ["{ " + ", ".join(repr(x) for x in k["p"][p]) + " }" for p in ORDER]
        L.append(f'\t\t\t{{ t = {k["t"]}, p = {{ ' + ", ".join(vals) + " } },")
    L.append('\t\t},')
    L.append('\t},')
L += ['} :: { [string]: Clip }', '', 'return UalClips', '']
open(out_path, "w", encoding="utf-8", newline="\n").write("\n".join(L))
print("written", out_path)
